SELECT (SELECT COUNT(*) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2025-10-31' AND loan_status<>'Closed'), (SELECT ROUND(SUM(closing_balance),0) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2025-10-31' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=30)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2025-10-31' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=90)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2025-10-31' AND loan_status<>'Closed'), (SELECT COUNT(*) FROM loan WHERE origination_date>date_trunc('month', DATE '2025-10-31')-INTERVAL 1 DAY AND origination_date<=DATE '2025-10-31'), (SELECT ROUND(SUM(original_amount),0) FROM loan WHERE origination_date>date_trunc('month', DATE '2025-10-31')-INTERVAL 1 DAY AND origination_date<=DATE '2025-10-31')
